INSERT INTO products (id, name, description, price, status, category_id, version, created_at, updated_at, thumbnail_url, tenant_id, seller_id) VALUES
  ('b0000000-0000-0000-0000-000000000009', '케이블 니트 스웨터', '도톰한 케이블 조직의 라운드넥 니트 스웨터입니다.', 79000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000004', 0, NOW(), NOW(), 'https://images.unsplash.com/photo-1574201635302-388dd92a4c3f?w=600&q=80&auto=format&fit=crop', 'ecommerce', 'default'),
  ('b0000000-0000-0000-0000-000000000010', '릴랙스 스웨트셔츠', '기모 안감의 루즈핏 스웨트셔츠입니다.', 52000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000004', 0, NOW(), NOW(), 'https://images.unsplash.com/photo-1620799140188-3b2a02fd9a77?w=600&q=80&auto=format&fit=crop', 'ecommerce', 'default'),
  ('b0000000-0000-0000-0000-000000000011', '코튼 치노 팬츠', '사계절용 코튼 트윌 원단의 스트레이트 치노입니다.', 62000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000005', 0, NOW(), NOW(), 'https://images.unsplash.com/photo-1473966968600-fa801b869a1a?w=600&q=80&auto=format&fit=crop', 'ecommerce', 'default'),
  ('b0000000-0000-0000-0000-000000000012', '와이드 슬랙스', '드레이프감이 좋은 와이드 핏 슬랙스입니다.', 68000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000005', 0, NOW(), NOW(), 'https://images.unsplash.com/photo-1584865288642-42078afe6942?w=600&q=80&auto=format&fit=crop', 'ecommerce', 'default'),
  ('b0000000-0000-0000-0000-000000000013', '노이즈 캔슬링 무선 이어버드', '액티브 노이즈 캔슬링과 30시간 재생을 지원하는 무선 이어버드입니다.', 189000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000002', 0, NOW(), NOW(), 'https://images.unsplash.com/photo-1572569511254-d8f925fe2cbb?w=600&q=80&auto=format&fit=crop', 'ecommerce', 'default'),
  ('b0000000-0000-0000-0000-000000000014', '포터블 블루투스 스피커', 'IPX7 방수 등급의 휴대용 블루투스 스피커입니다.', 129000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000002', 0, NOW(), NOW(), 'https://images.unsplash.com/photo-1608043152269-423dbba4e7e1?w=600&q=80&auto=format&fit=crop', 'ecommerce', 'default'),
  ('b0000000-0000-0000-0000-000000000015', '스마트워치 7', '심박·수면·운동 추적을 지원하는 스마트워치입니다.', 349000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000002', 0, NOW(), NOW(), 'https://images.unsplash.com/photo-1579586337278-3befd40fd17a?w=600&q=80&auto=format&fit=crop', 'ecommerce', 'default'),
  ('b0000000-0000-0000-0000-000000000016', '스페셜티 원두 500g', '에티오피아 싱글 오리진, 미디엄 로스팅 원두입니다.', 24000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000003', 0, NOW(), NOW(), 'https://images.unsplash.com/photo-1447933601403-0c6688de566e?w=600&q=80&auto=format&fit=crop', 'ecommerce', 'default'),
  ('b0000000-0000-0000-0000-000000000017', '엑스트라 버진 올리브오일 500ml', '콜드 프레스 방식으로 착유한 엑스트라 버진 올리브오일입니다.', 32000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000003', 0, NOW(), NOW(), 'https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?w=600&q=80&auto=format&fit=crop', 'ecommerce', 'default'),
  ('b0000000-0000-0000-0000-000000000018', '유기농 벌꿀 600g', '국내 산지에서 채밀한 유기농 아카시아 벌꿀입니다.', 28000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000003', 0, NOW(), NOW(), 'https://images.unsplash.com/photo-1587049352851-8d4e89133924?w=600&q=80&auto=format&fit=crop', 'ecommerce', 'default'),
  ('b0000000-0000-0000-0000-000000000019', '아이폰 17 프로', '티타늄 프레임과 개선된 카메라 시스템을 갖춘 프리미엄 스마트폰입니다.', 1690000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000006', 0, NOW(), NOW(), 'https://images.unsplash.com/photo-1592890288564-76628a30a657?w=600&q=80&auto=format&fit=crop', 'ecommerce', 'default'),
  ('b0000000-0000-0000-0000-000000000020', '픽셀 10 프로', 'AI 사진 보정에 강점을 둔 안드로이드 플래그십입니다.', 1290000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000006', 0, NOW(), NOW(), 'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?w=600&q=80&auto=format&fit=crop', 'ecommerce', 'default'),
  ('b0000000-0000-0000-0000-000000000021', '폴더블 스마트폰 Z6', '펼치면 7.6인치가 되는 폴더블 스마트폰입니다.', 2090000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000006', 0, NOW(), NOW(), 'https://images.unsplash.com/photo-1598327105666-5b89351aff97?w=600&q=80&auto=format&fit=crop', 'ecommerce', 'default'),
  ('b0000000-0000-0000-0000-000000000022', '울트라북 14인치', '1.1kg 무게의 휴대성 중심 14인치 울트라북입니다.', 1890000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000007', 0, NOW(), NOW(), 'https://images.unsplash.com/photo-1525547719571-a2d4ac8945e2?w=600&q=80&auto=format&fit=crop', 'ecommerce', 'default'),
  ('b0000000-0000-0000-0000-000000000023', '게이밍 노트북 16인치', '고주사율 디스플레이와 외장 그래픽을 갖춘 게이밍 노트북입니다.', 2590000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000007', 0, NOW(), NOW(), 'https://images.unsplash.com/photo-1496181133206-80ce9b88a853?w=600&q=80&auto=format&fit=crop', 'ecommerce', 'default'),
  ('b0000000-0000-0000-0000-000000000024', '2-in-1 컨버터블 노트북', '360도 힌지와 펜 입력을 지원하는 컨버터블 노트북입니다.', 1490000, 'ON_SALE', 'a0000000-0000-0000-0000-000000000007', 0, NOW(), NOW(), 'https://images.unsplash.com/photo-1486312338219-ce68d2c6f44d?w=600&q=80&auto=format&fit=crop', 'ecommerce', 'default');
